effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        float getBeat()
        {
            return 1.0;
        }

        #define k2PI (2.*3.14159265359)

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 image_size = getTexSize(inputImg.size);
        vec2 iRes = vec2(acScreenSize.x, acScreenSize.y);

        vec2 umefx;
        umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        umefx.y*=acLayerSize.y/acLayerSize.x;

        umefx /= scale;
        umefx *= rot2m((0.0+angle)*0.0174533);
        umefx += vec2((0.0+positionn.x), (0.0+positionn.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        umefx /= scaleVec;

        /////////////////////////

    	// vec4 fragColor;

            float ff = getBeat();
            vec2 resolution = iRes;
            float time = autop? EVO+(acTime*0.5) : EVO;
              vec2 p = umefx;
            p.x = p.x  * acScreenSize.x/ acScreenSize.y;
            vec2 position = p;


            float speed = 5.2 + smoothstep(0.8,12.0,ff) ;


              //position += mouse - 0.5; // use this for mouse panning

              float A = atan(position.y,position.x);
              float angle0 = A / k2PI;
              float angle = fract(angle0 + .0002*time);
              float rad = .4*length(position);
              float angleFract = fract(angle*kNumAngles);
              float angleStep = floor(angle*kNumAngles);
              float angleToRandZ = 10.*fract(angleStep*fract(angleStep*.7535)*45.1);
              float angleSquareDist = fract(angleStep*fract(angleStep*.82657)*13.724);
              float t = speed * time - angleToRandZ;
              float angleDist = (angleSquareDist+0.1);
              float adist = angleDist/rad*kStarDensity;
              float dist = abs(fract((t*.1+adist))-.5);
              float white1 = max(0.,1.0 - dist * 100.0 / (kMotionBlur*speed+adist));
              float white2 = max(0.,(.5-.5*cos(k2PI * angleFract))*1./max(0.6,2.*adist*angleDist));
              float white = white1*white2;
              vec4 fragColor = mix(colorbg, colorfg, white);
              // vec3 color;
              // color.r = .03*white1 + white*(0.3 + 5.0*angleDist);
              // color.b = white*(0.1 + .5*angleToRandZ);
              // color.g = 1.5*white;

              // fragColor = vec4( color, 0.0);

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        } else if( blendMode==3 ) {         // screen
            factor *= bright;
            resultfinal = (newLayer(texColor, factor) * bright) * texColor.a; }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
